const INFOG_SELLERBRIDER_G1 = { fr: HYPE_IMGS["k392"], en: HYPE_IMGS["k393"], ja: HYPE_IMGS["k394"], it: HYPE_IMGS["k395"], es: HYPE_IMGS["k396"], de: HYPE_IMGS["k397"] };
